from fastapi import APIRouter, Depends, HTTPException, Request

router = APIRouter(prefix="/realtime/merchants")

@router.get("/{merchant_id}/sales-volume")
async def get_merchant_realtime_volume(
    merchant_id: str,
    request: Request,
    current_user: User = Depends(get_current_user)
):
    if current_user.merchant_id != merchant_id and not current_user.is_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to query stream metrics for another merchant")

    faust_app = request.app.state.faust_stream_app
    hourly_table = faust_app.tables.get("merchant_hourly_volume")
    if hourly_table is None:
        raise HTTPException(status_code=503, detail="Faust stream table not ready")

    windowed_data = hourly_table[merchant_id]
    if not windowed_data:
        raise HTTPException(status_code=404, detail="No active stream data for merchant")

    return {
        "merchant_id": merchant_id,
        "current_hour_volume": windowed_data.value(),
        "transaction_count": windowed_data.count()
    }
